    "nav_sell": "விற்பனை ஆலோசகர்",
    "nav_weather": "வானிலை",
    "nav_schemes": "திட்டங்கள்",
    "nav_chat": "AI-யிடம் கேளுங்கள்",
    "hero_kicker": "விவசாயியின் தோழன் AI",
    "hero_welcome_back": "மீண்டும் வருக",
    "hero_welcome_guest": "வருக, விருந்தினரே — தாராளமாகப் பாருங்கள், கணக்கு தேவையில்லை.",
    "hero_welcome_new": "நமஸ்தே. உங்கள் விவசாயத் தோழனுக்கு வரவேற்கிறோம்.",
    "hero_sub": "விதைப்பு முதல் விற்பனை வரை முழு பயிர் சுழற்சியிலும் KrishiSathi உங்களுடன் பயணிக்கிறது. ஒரு புகைப்படத்திலிருந்து பயிரின் ஆரோக்கியத்தை சரிபார்க்கவும், நேரடி மண்டி விலைகளைப் பார்க்கவும், வானிலை எச்சரிக்கைகளை முன்கூட்டியே பெறவும், விற்க சரியான நேரத்தை அறியவும்.",
    "doctor_desc": "பாதிக்கப்பட்ட இலை, தண்டு அல்லது பழத்தின் தெளிவான புகைப்படத்தை பதிவேற்றவும். AI நோயை அல்லது பூச்சியை அடையாளம் கண்டு சிகிச்சை முறையை பரிந்துரைக்கும்.",
    "doctor_choose": "புகைப்படத்தைத் தேர்ந்தெடுக்க தட்டவும்",
    "doctor_note": "விருப்பக் குறிப்பு (பயிர், எவ்வளவு நேரம், செடியில் எங்கு உள்ளது...)",
    "doctor_diagnose": "புகைப்படத்தை பகுப்பாய்வு செய்க",
    "doctor_analysing": "பகுப்பாய்வு செய்கிறது...",
    "mandi_desc": "அரசு AGMARKNET தரவிலிருந்து நேரடி மொத்த விற்பனை விலைகள் (₹ ஒரு குவிண்டாலுக்கு). உங்களுக்கு அருகிலுள்ள சிறந்த சந்தையைக் கண்டறிய சந்தைகளை ஒப்பிடுக.",
    "mandi_commodity": "பொருள்",
    "mandi_state": "மாநிலம்",
    "mandi_district": "மாவட்டம் (விருப்பப்பட்டால்)",
    "mandi_show": "விலைகளைக் காட்டு",
    "mandi_avg": "சராசரி மாதிரி விலை",
    "mandi_range": "இன்றைய விலை வரம்பு",
    "mandi_best": "சிறந்த சந்தை",
    "mandi_trend": "சமீபத்திய விலை போக்கு",
    "sell_desc": "உங்கள் பயிர் மற்றும் செலவுகளை உள்ளிடவும். KrishiSathi அவற்றை நேரடி மண்டி விலைகளுடன் ஒப்பிட்டு ஆலோசனை வழங்குகிறது: இப்போது விற்கவும், பிடித்து வைக்கவும், குளிர்ந்த சேமிப்பகத்தைப் பயன்படுத்தவும் அல்லது நேரடி வாங்குபவரைத் தேடவும்.",
    "sell_qty": "விற்க வேண்டிய அளவு (குவிண்டால்கள்)",
